import { spawnSync } from 'node:child_process';
import { writeFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test2_executable';
const t0 = Date.now();
// chunked scan of codepoints
const results = new Map(); // cp -> 'lit' | escape string
const CHUNK = 2048;
let bad = [];
for (let base = 0x80; base < 0x110000; base += CHUNK) {
  const cps = [];
  for (let c = base; c < Math.min(base + CHUNK, 0x110000); c++) {
    if (c >= 0xd800 && c <= 0xdfff) continue;
    cps.push(c);
  }
  if (!cps.length) continue;
  const input = 'a.' + cps.map(c => String.fromCodePoint(c)).join('.') + '.a';
  const r = spawnSync(EXE, ['--a', input], { encoding: 'utf8', maxBuffer: 1 << 28 });
  if (r.status !== 0) { bad.push([base, 'status ' + r.status, r.stderr]); continue; }
  let out = r.stdout.replace(/\n$/, '');
  // strip [' and ']
  if (!(out.startsWith("['") && out.endsWith("']"))) { bad.push([base, 'shape', out.slice(0,80)]); continue; }
  const body = out.slice(2, -2);
  const parts = body.split('.');
  if (parts.length !== cps.length + 2 || parts[0] !== 'a' || parts[parts.length-1] !== 'a') {
    bad.push([base, 'parts ' + parts.length + ' vs ' + (cps.length+2), JSON.stringify(parts.slice(0,5))]);
    continue;
  }
  for (let i = 0; i < cps.length; i++) {
    results.set(cps[i], parts[i+1]);
  }
}
console.log('elapsed ms', Date.now() - t0, 'entries', results.size, 'bad', bad.length);
for (const b of bad.slice(0, 20)) console.log('BAD', b[0].toString(16), b[1], b[2]);
const obj = {};
for (const [k, v] of results) obj[k] = v;
writeFileSync('/workspace/tmp/scan.json', JSON.stringify(obj));
EOF
