  const r = spawnSync(EXE, ['--a', s], { encoding: 'utf8', maxBuffer: 1 << 28 });
  return { out: r.stdout, code: r.status, err: r.stderr };
};
// 200 statements -> single line, no wrapping?
let many = [];
for (let i = 0; i < 200; i++) many.push('SELECT ' + i + ';');
let r = run(many.join(' '));
console.log('200 stmts: newlines in stdout =', (r.out.match(/\n/g) || []).length, 'len =', r.out.length, 'code', r.code);
console.log('head:', JSON.stringify(r.out.slice(0, 60)));
console.log('tail:', JSON.stringify(r.out.slice(-60)));
// long single item with escapes
const big = 'a' + '͸'.repeat(500) + 'b';
r = run(big);
console.log('long escapes: len', r.out.length, 'expected', 2 + 1 + 500 * 6 + 1 + 2 + 1, 'newlines', (r.out.match(/\n/g) || []).length);
// mixed quotes across many items
r = run("a'1; b\"2; c'3\"4; d");
console.log('mixed:', JSON.stringify(r.out));
// astral output byte check
r = spawnSync(EXE, ['--a', 'a\u{1F600}b'], { maxBuffer: 1 << 28 });
console.log('astral bytes:', [...r.stdout].map(b => b.toString(16)).join(' '));

import { spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test2_executable';
const scan = JSON.parse(readFileSync('/workspace/tmp/scan.json', 'utf8'));

// ---- cross-check bulk scan against individual probes on random codepoints ----
const keys = Object.keys(scan);
let bad = 0, checked = 0;
const rnd = [];
for (let i = 0; i < 120; i++) rnd.push(Number(keys[Math.floor(Math.random() * keys.length)]));
// plus deliberately interesting boundaries
for (const c of [0x80, 0x9f, 0xa0, 0xa1, 0xac, 0xad, 0xae, 0x2fff, 0x3000, 0x3001, 0xd7ff, 0xe000,
                 0xfffc, 0xfffd, 0xfffe, 0x10000, 0x10ffff, 0x1f600, 0xe01ef, 0xe01f0, 0x2ebef, 0x2ebf0]) rnd.push(c);
for (const cp of rnd) {
  const r = spawnSync(EXE, ['--a', 'a' + String.fromCodePoint(cp) + 'b'], { encoding: 'utf8' });
  const got = r.stdout.slice(3, -3); // strip "['a" ... "b']\n"
  checked++;
  if (got !== scan[String(cp)]) { bad++; console.log('DISAGREE', cp.toString(16), JSON.stringify(got), JSON.stringify(scan[String(cp)])); }
}
console.log('cross-check:', checked, 'checked,', bad, 'disagreements');

// ---- build the definitive non-printable range table over 0x00..0x10FFFF ----
const nonPrintable = [];
for (let cp = 0; cp < 0x110000; cp++) {
  let np;
  if (cp === 0x00) np = true;                       // INFERRED (unreachable via argv)
  else if (cp < 0x20) np = true;                    // confirmed individually
  else if (cp < 0x7f) np = false;                   // confirmed individually (0x20..0x7e)
  else if (cp === 0x7f) np = true;                  // confirmed
  else if (cp >= 0xd800 && cp <= 0xdfff) np = true; // Cs; DC80..DCFF confirmed, rest inferred
  else np = scan[String(cp)] !== String.fromCodePoint(cp);
  if (np) {
    const last = nonPrintable[nonPrintable.length - 1];
    if (last && last[1] === cp - 1) last[1] = cp; else nonPrintable.push([cp, cp]);
  }
}
console.log('non-printable ranges:', nonPrintable.length,
  'total codepoints:', nonPrintable.reduce((a, r) => a + r[1] - r[0] + 1, 0));
writeFileSync('/workspace/spec/python-nonprintable-ranges.json',
  JSON.stringify({
    note: 'Codepoint ranges (inclusive, decimal) that CPython str.__repr__ escapes. Derived black-box from /workspace/dataset/test2_executable by scanning every codepoint 0x80..0x10FFFF. UCD 15.0.0.',
    confirmed: '0x01-0x1F, 0x7F, and every cp in 0x80..0x10FFFF (excluding surrogates) observed directly. 0x00 inferred (unreachable via argv). D800-DFFF: DC80-DCFF observed, rest inferred from category Cs.',
    ranges: nonPrintable,
  }));
const h = n => n.toString(16).toUpperCase().padStart(4, '0');
writeFileSync('/workspace/tmp/ranges-pretty.txt',
  nonPrintable.map(r => r[0] === r[1] ? h(r[0]) : h(r[0]) + '..' + h(r[1])).join(' '));
console.log('pretty written');

