import { writeFileSync } from 'node:fs';
const U = (h) => String.fromCodePoint(parseInt(h, 16));
const cases = [];
const add = (s) => cases.push(s);

// ---------- 1. quote selection ----------
add('a');                       // no quotes present         -> '...'
add("a'b");                     // ' only                    -> "..."
add('a"b');                     // " only                    -> '...'
add('a\'b"c');                  // both                      -> '...' with \'
add('a"b\'c');                  // both, other order
add("'");
add('"');
add("''");
add("''''");
add('""');
add("it's");
add('say "hi"');
add('both \' and "');
add('a\\b');                    // single backslash
add('a\\\\b');                  // double backslash
add("a\\'b");                   // backslash + '
add('a\\"b');                   // backslash + "
add("a\\'b\"c");                // backslash + both quotes
add("'a'b\\c");
add('SELECT \'e\'');
add("SELECT 'é'");

// ---------- 2. C0 controls, one at a time ----------
for (let i = 1; i <= 0x1f; i++) add('a' + String.fromCharCode(i) + 'b');
add('a b');                     // 0x20 stays literal
add('a' + U('7f') + 'b');       // DEL

// ---------- 3. C1 + Latin-1 boundary ----------
for (const h of ['80', '85', '8a', '9f', 'a0', 'a1', 'ac', 'ad', 'ae', 'b5', 'e9', 'ff']) add('a' + U(h) + 'b');

// ---------- 4. named vs numeric escapes ----------
add('x\ty');
add('x\ny');
add('x\ry');
add('x\r\ny');
add('a' + U('07') + 'b');       // BEL  -> \x07 (NOT \a)
add('a' + U('08') + 'b');       // BS   -> \x08 (NOT \b)
add('a' + U('0b') + 'b');       // VT   -> \x0b (NOT \v)
add('a' + U('0c') + 'b');       // FF   -> \x0c (NOT \f)
add('a' + U('1b') + 'b');       // ESC

// ---------- 5. BMP non-printables (\uXXXX) ----------
for (const h of ['378', '380', '38b', '3a2', '557', '5c8', '600', '605', '61c', '6dd', '70f', '8e2',
                 '1680', '180e', '2000', '200a', '200b', '200c', '200d', '200e', '200f',
                 '2028', '2029', '202a', '202f', '205f', '2060', '2066', '206f',
                 '2ffc', '2fff', '3000', '3040', '31ef', 'd7ff', 'e000', 'f8ff',
                 'fdd0', 'fdef', 'feff', 'fff9', 'fffb', 'fffe', 'ffff']) add('a' + U(h) + 'b');

// ---------- 6. BMP printables kept literally ----------
for (const h of ['100', '17f', '2b0', '300', '374', '384', '3b1', '400', '410', '483', '488', '531',
                 '591', '870', '2070', '3001', 'd7fb', 'f900', 'fffc', 'fffd', '4e2d', '5b57',
                 '2dfb', '1358', 'c26c']) add('a' + U(h) + 'b');

